$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\moham\fidelity-image-viewer"

if (-not (Test-Path $RepoPath)) {
    Write-Host "[ERROR] Repository path not found: $RepoPath" -ForegroundColor Red
    exit 1
}

Set-Location $RepoPath
Write-Host "[1/3] Writing hardened src/routes/leaderboard.tsx and src/lib/f1-sync.functions.ts..." -ForegroundColor Cyan

function Write-RepoFile {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )
    $FullPath = Join-Path $RepoPath $RelativePath
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host "  [OK] Updated $RelativePath ($($Bytes.Length) bytes)" -ForegroundColor Green
}

Write-RepoFile -RelativePath 'src/routes/leaderboard.tsx' -Base64Content ''
Write-RepoFile -RelativePath 'src/lib/f1-sync.functions.ts' -Base64Content ''

Write-Host "[2/3] Verifying standings snapshot integrity and TypeScript syntax..." -ForegroundColor Cyan
